    # stripe (2 columns separated by 0), restore isolated erroneous cells by
    # imposing the pattern indicated by the neighboring same-parity rows.
    out=[r[:] for r in grid]
    starts=(0,3,6,9,12)
    for r in range(1,len(grid),2):
        for s in starts:
            # nearest established row-pattern repetitions above/below
            if r+2 < len(grid):
                for j in (0,1):
                    vals=[grid[k][s+j] for k in (r-2,r+2) if 0<=k<len(grid)]
                    if vals and len(set(vals))==1:
                        out[r][s+j]=vals[0]
    return out
